package com.ieum.dodam.welfare.domain.entity;
import jakarta.persistence.*; import lombok.AccessLevel; import lombok.Getter; import lombok.NoArgsConstructor; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import com.fasterxml.jackson.databind.JsonNode; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="welfare_recommendation_items") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class WelfareRecommendationItem { @Id private UUID id; @Column(name="run_id",nullable=false) private UUID runId; @Column(name="program_id",nullable=false) private UUID programId; @Enumerated(EnumType.STRING) @Column(name="recommendation_type",nullable=false) private RecommendationType recommendationType; @Enumerated(EnumType.STRING) @Column(name="eligibility_status",nullable=false) private EligibilityStatus eligibilityStatus; @Column(nullable=false,precision=5,scale=2) private BigDecimal score; @JdbcTypeCode(SqlTypes.JSON) @Column(name="matched_conditions",nullable=false,columnDefinition="jsonb") private JsonNode matchedConditions; @JdbcTypeCode(SqlTypes.JSON) @Column(name="missing_conditions",nullable=false,columnDefinition="jsonb") private JsonNode missingConditions; @Column(name="created_at",nullable=false) private Instant createdAt; public enum RecommendationType { PROACTIVE, SUGGESTIVE } public enum EligibilityStatus { ELIGIBLE, POSSIBLE, INELIGIBLE, EXPIRED } }
